// Общие шаги для тестов вкладки Plans, которые ПИШУТ данные (@writes).
// Единственная разрешённая цель записи — аккаунт «בדיקה» (wojeg27104@blobapps.com).
import { expect, Locator, Page } from '@playwright/test';

export const TARGET_EMAIL = 'wojeg27104@blobapps.com';
export const TARGET_NAME = 'בדיקה';

/** Язык интерфейса хранится в localStorage 'preferred-language' ('en' | 'he'). Ставим до загрузки страницы. */
export async function setLanguage(page: Page, lang: 'en' | 'he') {
  await page.addInitScript((l) => {
    try { window.localStorage.setItem('preferred-language', l); } catch { /* ignore */ }
  }, lang);
}

/** YYYY-MM-DD (локальная дата) со сдвигом в днях от сегодня. */
export function isoDate(offsetDays: number): string {
  const d = new Date();
  d.setDate(d.getDate() + offsetDays);
  const p = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

/** Дата так, как её показывает EN-интерфейс: «Nov 3, 2026». */
export function enDate(offsetDays: number): string {
  const d = new Date();
  d.setDate(d.getDate() + offsetDays);
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

export async function openPlansTab(page: Page) {
  await page.goto('/adminpanel');
  await page.getByRole('tab', { name: 'Plans', exact: true })
    .or(page.getByRole('button', { name: 'Plans', exact: true }))
    .first()
    .click();
  await expect(page.getByRole('heading', { name: 'Plans' })).toBeVisible();
}

/** Ищет «בדיקה» и возвращает её строку. Падает, если строка не одна — защита от записи в чужой аккаунт. */
export async function targetRow(page: Page): Promise<Locator> {
  const search = page.getByRole('searchbox').or(page.getByRole('textbox')).first();
  await search.fill(TARGET_EMAIL);
  const rows = page.locator('tr, [role="row"]').filter({ hasText: TARGET_EMAIL });
  await expect(rows).toHaveCount(1);
  const row = rows.first();
  await expect(row).toContainText(TARGET_NAME);
  return row;
}

export function dialogFields(page: Page) {
  const dialog = page.getByRole('dialog');
  return {
    dialog,
    plan: dialog.getByLabel('Plan', { exact: true }).or(dialog.getByRole('combobox')).first(),
    until: dialog.getByLabel('Until (inclusive)').or(dialog.locator('input[type="date"]')).first(),
    reason: dialog.getByLabel('Reason').or(dialog.getByRole('textbox').last()).first(),
    save: dialog.getByRole('button', { name: 'Save', exact: true }),
    revoke: dialog.getByRole('button', { name: 'Revoke', exact: true }),
  };
}

/** Выбор тарифа: нативный select или кастомный список. */
export async function choosePlan(page: Page, plan: Locator, name: string) {
  const tag = await plan.evaluate((el) => el.tagName.toLowerCase());
  if (tag === 'select') {
    await plan.selectOption({ label: name });
  } else {
    await plan.click();
    await page.getByRole('option', { name, exact: true }).click();
  }
}

/** Очистка: если у «בדיקה» есть ручное назначение — отменить. Безопасно вызывать всегда (в finally). */
export async function revokeIfAssigned(page: Page, reason = 'QA-AUTO cleanup revoke') {
  await openPlansTab(page);
  const row = await targetRow(page);
  const revokeBtn = row.getByRole('button', { name: 'Revoke', exact: true });
  if (await revokeBtn.count() === 0 || !(await revokeBtn.isVisible())) return;
  await revokeBtn.click();
  const f = dialogFields(page);
  await f.reason.fill(reason);
  await f.revoke.click();
  await expect(f.dialog).toBeHidden();
  await expect(row.getByRole('button', { name: 'Assign plan', exact: true })).toBeVisible();
}
